import { QNotifyCreateOptions } from 'quasar';
// Import types from Quasar if available
interface NotificationAction {
  label: string;
  handler?: () => void;
}

interface NotificationOptions {
  title?: string;
  message?: string;
  type?: 'info' | 'warning' | 'error' | 'success';
  timeout?: number;
  actions?: Array<NotificationAction>;
  position?: string;
  onClose?: () => void;
}

// Define a custom type for $q
export interface QuasarNotify {
  notify: (options: QNotifyCreateOptions) => any;
}

/**
 *
 * @param $q
 */
export function useNotify($q: QuasarNotify) {
  // Helper function to create HTML for the notification
  const createNotificationHtml = (options: NotificationOptions): string => {
    const { title = '', message = '', type = 'info', actions = [] } = options;

    // Define icons based on type
    let iconHtml = '';
    switch (type) {
      case 'warning': {
        iconHtml = `<div class="icon-wrapper warning-icon"><i class="material-icons">warning</i></div>`;

        break;
      }
      case 'error': {
        iconHtml = `<div class="icon-wrapper error-icon"><i class="material-icons">error</i></div>`;

        break;
      }
      case 'success': {
        iconHtml = `<div class="icon-wrapper success-icon"><i class="material-icons">check</i></div>`;

        break;
      }
      default: {
        // Info
        iconHtml = `<div class="icon-wrapper info-icon"><i class="material-icons">info</i></div>`;
      }
    }

    return `
      <div class="notification-wrapper notification-${type} ${actions.length > 0 ? 'with-actions' : ''}">
        <div class="notification-content">
          <div class="notification-icon">
            ${iconHtml}
          </div>
          <div class="notification-text">
            <div class="notification-title">${title}</div>
            <div class="notification-body">${message}</div>
          </div>
          <div class="notification-close">
            <button class="close-btn" aria-label="Close notification">×</button>
          </div>
        </div>
        ${
          actions.length > 0
            ? `
          <div class="notification-actions">
            ${actions
              .map(
                (action: NotificationAction, index: number) => `
              <button class="notification-action-btn action-btn" data-action-index="${index}">${action.label}</button>
            `,
              )
              .join('')}
          </div>
        `
            : ''
        }
      </div>
    `;
  };

  // Setup global CSS if not already added

  // Base notification function
  const showNotification = (options: NotificationOptions): any => {
    const {
      title = 'Title',
      message = 'Body text.',
      type = 'info',
      timeout = 5000,
      actions = [],
      position = 'top-right',
      onClose = () => {},
    } = options;

    // Setup DOM event listener for action buttons
    const handleActionClick = (event: Event): void => {
      const target = event.target as HTMLElement;
      if (target.classList.contains('notification-action-btn')) {
        const actionIndex = Number.parseInt(
          target.dataset.actionIndex ?? '',
          10,
        );
        actions[actionIndex]?.handler?.();
      }
    };

    // Setup close button handler
    const handleCloseClick = (event: Event): void => {
      const target = event.target as HTMLElement;
      if (target.classList.contains('close-btn')) {
        const notificationElement = target.closest('.notification-wrapper');
        if (notificationElement) {
          // Use a valid method to close the notification
          notificationElement.remove(); // Manually remove the notification element
        }
      }
    };

    // Create and return the notification
    const notification = $q.notify({
      html: true,
      position: position as
        | 'top-right'
        | 'top-left'
        | 'bottom-left'
        | 'bottom-right'
        | 'top'
        | 'bottom', // Ensure type compatibility
      timeout,
      message: createNotificationHtml({ title, message, type, actions }),
      onDismiss: () => {
        document.removeEventListener('click', handleActionClick);
        document.removeEventListener('click', handleCloseClick);
        onClose();
      },
    });

    document.addEventListener('click', handleActionClick);
    document.addEventListener('click', handleCloseClick);

    return notification;
  };

  // Create type-specific notification functions
  return {
    show: showNotification,
    info: (options: NotificationOptions) =>
      showNotification({ ...options, type: 'info' }),
    warning: (options: NotificationOptions) =>
      showNotification({ ...options, type: 'warning' }),
    error: (options: NotificationOptions) =>
      showNotification({ ...options, type: 'error' }),
    success: (options: NotificationOptions) =>
      showNotification({ ...options, type: 'success' }),
  };
}

