import axios from 'axios';
import { appLogger } from '../../../utils/logger/app-logger';
import { UserAttribute } from '../dto/user-attribute.dto';
import { UserResponse } from '../dto/user-response.dto';
import { User } from '../dto/user.dto';
import { Permission } from '../dto/user.permission.dto';

export class ApiService {
  private readonly umeBaseUrl: string;

  private readonly token: string;

  private readonly appName: string;

  public getDynamicActions = async (
    roles: string,
  ): Promise<Array<Permission>> => {
    try {
      // Make the API request to the backend
      const response = await axios.get(
        `${this.umeBaseUrl}/permission-definition/${this.appName}`,

        {
          headers: {
            authorization: `Bearer ${this.token}`,
          },
          params: {
            roles,
          },
        },
      );

      const permissions: Array<Permission> = response.data;

      // Return the permissions in the required format
      return permissions.map((permission) => ({
        actionType: permission.actionType,
        object: permission.object,
      }));
    } catch (error) {
      console.error('Error fetching dynamic actions:', error);
      return []; // Return an empty array on error
    }
  };

  public constructor(umeBaseUrl: string, token: string, appName: string) {
    this.umeBaseUrl = umeBaseUrl;
    this.token = token;
    this.appName = appName;
  }

  public async getUserAttributesByUserId(
    userId: number,
  ): Promise<Array<UserAttribute>> {
    try {
      const response = await axios.get(
        `${this.umeBaseUrl}/user-attribute-mapping/${userId}`,
        {
          headers: {
            authorization: `Bearer ${this.token}`,
          },
        },
      );
      const userAttributes = response.data;
      return userAttributes;
    } catch (error) {
      appLogger.error('Error fetching user attributes');
      throw error;
    }
  }

  public async saveUser(users: User): Promise<User> {
    const payload = { ...users };

    const response = await axios.post(`${this.umeBaseUrl}/users`, payload, {
      headers: {
        authorization: `Bearer ${this.token}`,
      },
    });

    return response.data;
  }

  public async getUserByEmail(email: string): Promise<UserResponse> {
    const response = await axios.get(
      `${this.umeBaseUrl}/users/email/${email}`,
      {
        headers: {
          authorization: `Bearer ${this.token}`,
        },
      },
    );

    return response.data;
  }

  public async updateUserLastLoginByEmail(
    email: string,
    lastLogin: Date,
  ): Promise<string> {
    const response = await axios.put(
      `${this.umeBaseUrl}/users/${email}/last-login`,
      { lastLogin },
      {
        headers: {
          authorization: `Bearer ${this.token}`,
        },
      },
    );

    return response.data;
  }

  public async checkPermission(roleNames: string): Promise<boolean> {
    try {
      const response = await axios.get<boolean>(
        `${this.umeBaseUrl}/permissions/${this.appName}`,
        {
          headers: {
            authorization: `Bearer ${this.token}`,
          },
          params: { roleNames },
        },
      );

      return response.data;
    } catch {
      appLogger.error('Check permission failed');
      return false;
    }
  }
}

import { BroadcastChannel, createLeaderElection } from 'broadcast-channel';
import { UserManager, User, UserSettings } from 'oidc-client';
import { appLogger } from '../../../utils/logger/app-logger.ts';
import { AuthConfigDTO } from '../dto/config.dto.ts';

const TOKEN_RESPONSE_EVENT = 'request-token-update-response';

export class AuthConfigService {
  private readonly userManager: UserManager;

  private readonly tokenChannel = new BroadcastChannel<{
    type: string;
    user?: UserSettings;
  }>('auth-token-sync');

  private readonly leaderElector = createLeaderElection(this.tokenChannel);

  private isLeaderTab = false;

  private readonly localEmitter = new EventTarget();

  private isRefreshing = false;

  private refreshPromise: Promise<void> | null = null;

  public constructor(authConfig: AuthConfigDTO) {
    this.userManager = new UserManager(authConfig);
    this.userManager.events.addAccessTokenExpiring(async () => {
      appLogger.log(
        'Access token is about to expire. Attempting silent refresh...',
      );
      await this.refreshToken();
    });

    this.subscribeToTokenUpdates();
  }

  // Getleader()
  public getLeader(): boolean {
    return this.isLeaderTab;
  }

  public getTokenChannel(): BroadcastChannel {
    return this.tokenChannel;
  }

  public getUserManager(): UserManager {
    return this.userManager;
  }

  public async hasLeader(): Promise<boolean> {
    return this.leaderElector.hasLeader();
  }

  public async requestTokenFromLeader(): Promise<void> {
    return new Promise<void>((resolve) => {
      this.localEmitter.addEventListener(
        TOKEN_RESPONSE_EVENT,
        () => resolve(),
        {
          once: true,
        },
      );
      this.tokenChannel.postMessage({
        type: 'request-token',
      });
    });
  }

  public async becomeLeaderIfElected(): Promise<boolean> {
    try {
      await this.leaderElector.awaitLeadership();
      this.isLeaderTab = true;
      appLogger.log('[Leader] This tab is elected as leader.');
      return true;
    } catch (error) {
      this.isLeaderTab = false;
      appLogger.warn(`[Follower] Not elected as leader: ${error}`);
      return false;
    }
  }

  private subscribeToTokenUpdates(): void {
    this.tokenChannel.addEventListener('message', async (message) => {
      if (
        ['request-token-update-response', 'token-update'].includes(
          message.type,
        ) &&
        message.user
      ) {
        // Follower side
        appLogger.log(`[Follower] Received token-update from leader tab.`);
        try {
          const hydratedUser = new User(message.user);
          await this.userManager.storeUser(hydratedUser);
          if (message.type === 'request-token-update-response') {
            this.localEmitter.dispatchEvent(new Event(TOKEN_RESPONSE_EVENT));
          }
          appLogger.log('[Follower] Stored user from leader successfully.');
        } catch (error) {
          appLogger.error(`[Follower] Failed to store user: ${error}`);
        }
      }

      if (this.isLeaderTab && message.type === 'request-token') {
        try {
          const user = await this.userManager.getUser();
          if (user) {
            const rawUser = JSON.parse(user.toStorageString());
            appLogger.log(
              '[Leader] Received token request, sending token-update',
            );
            this.tokenChannel.postMessage({
              type: 'request-token-update-response',
              user: rawUser,
            });
          } else {
            appLogger.warn('[Leader] No user to send to follower');
          }
        } catch (error) {
          appLogger.error(`[Leader] Failed to respond with token: ${error}`);
        }
      }
    });
  }

  /**
   * Retrieves the current user's information.
   */
  public getUser(): Promise<User | null> {
    return this.userManager.getUser();
  }

  /**
   * Checks if the user is authenticated.
   *
   * This function uses the `userManager` to retrieve the current user and determines
   * whether they are authenticated. If an error occurs during the process, it logs the
   * error and returns `false`.
   * @returns - A promise that resolves to `true` if the user is authenticated, or `false` otherwise.
   */
  public async isAuthenticated(): Promise<boolean> {
    try {
      const user = await this.getUser();
      return user !== null; // Returns true if the user is authenticated, otherwise false
    } catch (error) {
      appLogger.error(`Error checking authentication status: ${error}`);
      return false; // Return false in case of an error
    }
  }

  /**
   * Logs in the user by redirecting to the authentication provider.
   */
  public async login(): Promise<void> {
    const user = await this.getUser();
    if (user) {
      return; // If the user is already authenticated, no need to log in again.
    }

    // Create a "state" object that contains the data to be passed
    const state = {
      targetRoute: window.location.pathname, // Pass the requested page URL
    };
    // Redirect the user to PingFederate with the state object
    await this.userManager.signinRedirect({ state });
  }

  public async refreshToken(): Promise<void> {
    if (!this.isLeaderTab) return;

    if (this.refreshPromise) return this.refreshPromise;

    this.refreshPromise = (async () => {
      if (this.isRefreshing) return;
      this.isRefreshing = true;

      try {
        const refreshedUser = await this.userManager.signinSilent();
        if (refreshedUser) {
          await this.userManager.storeUser(refreshedUser);
          appLogger.log('[Leader] Token refreshed successfully.');
          const rawUser = JSON.parse(refreshedUser.toStorageString());
          this.tokenChannel.postMessage({
            type: 'token-update',
            user: rawUser,
          });
        } else {
          appLogger.error('[Leader] Silent refresh failed: user is null');
        }
      } catch (error) {
        appLogger.error(`[Leader] Error during silent refresh: ${error}`);
      } finally {
        this.isRefreshing = false;
        this.refreshPromise = null;
      }
    })();

    return this.refreshPromise;
  }

  /**
   * Handles the redirect callback after authentication.
   * @param router
   */
  public async handleRedirectCallback(router: any): Promise<void> {
    try {
      // Handling the callback after authentication redirection
      const user = await this.userManager.signinRedirectCallback();

      if (user?.state) {
        const { state } = user; // Retrieve the state object sent during authentication
        if (router && state.targetRoute) {
          // Ensure that the target URL is properly defined
          router.replace(state.targetRoute); // Use `replace` to prevent the previous page from being stored in the history
        }
      }
    } catch (error) {
      throw new Error(`Error while processing the redirect callback: ${error}`);
    }
  }

  /**
   * Initializes authentication by checking if a redirect was made and handling it.
   * @param router
   */
  public async initializeAuthentication(router: any): Promise<void> {
    try {
      const wasRedirected = localStorage.getItem('redirectedFromPingFederate');
      if (wasRedirected) {
        await this.handleRedirectCallback(router);
        localStorage.removeItem('redirectedFromPingFederate');
      }

      const user = await this.getUser();
      if (user) {
        appLogger.log('Authentication successful');
        const rawUser = JSON.parse(user.toStorageString());
        this.tokenChannel.postMessage({
          type: 'token-update',
          user: rawUser,
        });
      } else {
        localStorage.setItem('redirectedFromPingFederate', 'true');
        await this.login();
      }
    } catch (error) {
      // Stop the process to avoid infinite loop
      localStorage.removeItem('redirectedFromPingFederate');
      throw new Error(`Authentication initialization failed: ${error}`);
    }
  }

  /**
   * Logs out the user by redirecting to the authentication provider.
   */
  public async logout(): Promise<void> {
    try {
      await this.userManager.signoutRedirect();
    } catch (error) {
      appLogger.error(`Error during logout:${error}`);
    }
  }
}

import { appLogger } from '../../../utils/logger/app-logger.ts';
import useUserStore from '../store/user-store.ts';
import { ApiService } from './auth-api';
import { AuthConfigService } from './auth.config.ts';

// Custom error interface
interface CustomError extends Error {
  response?: {
    status: number;
  };
}
/**
 * Authenticates the user and updates their profile.
 * @param authService
 * @param apiService
 */
export const authenticateUser = async (
  authService: AuthConfigService,
  apiService: ApiService,
): Promise<void> => {
  try {
    const user = await authService.getUser();
    const userstore = useUserStore();
    let userLoggedIn = false;

    if (!user) {
      appLogger.error('No user information found.');
      return;
    }

    const userDetails = {
      email: user.profile.email ?? '',
      firstName: user.profile.given_name ?? '',
      fullName: `${user.profile.family_name ?? ''} ${user.profile.given_name ?? ''}`,
      lastLogin: new Date(),
      lastName: user.profile.family_name ?? '',
    };

    try {
      const fetchedUser = await apiService.getUserByEmail(userDetails.email);
      localStorage.setItem('userId', fetchedUser.userId);
      userstore.setProfile(userDetails.fullName);
      userLoggedIn = true;
    } catch (error) {
      const customError = error as CustomError;
      if (customError.response && customError.response.status === 404) {
        userLoggedIn = false;
      } else {
        appLogger.error(`Error during user authentication:${error}`);
        throw error;
      }
    }

    if (userLoggedIn) {
      userDetails.lastLogin = new Date();
      await apiService.updateUserLastLoginByEmail(
        userDetails.email,
        userDetails.lastLogin,
      );
    } else {
      await apiService.saveUser(userDetails);
      userstore.setProfile(userDetails.fullName);
    }
  } catch (error) {
    appLogger.error(`Authentication failed:${error}`);
  }
};

/**
 * Authorizes the user based on their role and screen type.
 * @param apiService
 * @param roleNames
 * @param router
 * @param appBasePath
 */
export const authorizeUser = async (
  apiService: ApiService,
  roleNames: string,
  router: any,
  appBasePath: string,
): Promise<boolean> => {
  if (!roleNames) {
    await router.push(`${appBasePath}/unauthorized`);
    return false;
  }

  try {
    const authorized = await apiService.checkPermission(roleNames);
    if (!authorized) {
      await router.push(`${appBasePath}/unauthorized`);
    }
    return !!authorized;
  } catch {
    appLogger.error('Authorization failed');
    await router.push(`${appBasePath}/unauthorized`);
    return false;
  }
};
/**
 * Authorizes the user based on their role and screen type.
 * @param apiService
 * @param roleNames
 * @param router
 * @param appBasePath
 */
export const authorizeUserWithPermissions = async (
  apiService: ApiService,
  roleNames: string,
  router: any,
  appBasePath: string,
): Promise<{
  isAuthorized: boolean;
  actions: Array<{ actionType: string; object: string }>;
}> => {
  if (!roleNames) {
    await router.push(`${appBasePath}/unauthorized`);
    return { isAuthorized: false, actions: [] };
  }

  try {
    const authorized = await apiService.checkPermission(roleNames);
    if (!authorized) {
      await router.push(`${appBasePath}/unauthorized`);
      return { isAuthorized: false, actions: [] };
    }

    const permissions = await apiService.getDynamicActions(roleNames);

    const actions = permissions.map((permission) => ({
      actionType: permission.actionType,
      object: permission.object,
    }));
    return { isAuthorized: true, actions };
  } catch (error) {
    appLogger.error(`Authorization failed: ${error}`);
    await router.push(`${appBasePath}/unauthorized`);
    return { isAuthorized: false, actions: [] };
  }
};

export const extractGroupNames = async (
  groups: Array<string>,
): Promise<Array<string>> => {
  const regex = /^CN=([^,]+)/; // Extract the group name after 'CN='
  const roleRegex = /^WW_([^_]+(?:_[^_]+)*)_\w+$/;
  return groups.map((group) => {
    const match = regex.exec(group)?.[1]?.toUpperCase(); // Extract role name
    if (match?.startsWith('WW_')) {
      const coreRole = roleRegex.exec(match)?.[1]; // Extract core role without SID
      return coreRole ? coreRole.toUpperCase() : match; // Return core role if extracted
    }
    return match ?? ''; // Return original role if no match
  });
};

import { getUserId } from '../../../local-storage/user-attribute.ts';
import { useLocalizationStore } from '../../../ui/store/localization-store.ts';
import { appLogger } from '../../../utils/logger/app-logger.ts';
import { UserAttribute } from '../dto/user-attribute.dto';
import { ApiService } from './auth-api';

export class UserAttributesManager {
  private readonly userAttributes: { [key: string]: string } = {};

  private readonly apiService: ApiService;

  public constructor(apiService: ApiService) {
    this.apiService = apiService;
  }

  public transformAttributesToStorageFormat(attributes: Array<UserAttribute>): {
    [key: string]: string;
  } {
    const transformed: { [key: string]: string } = {};
    for (const attribute of attributes) {
      transformed[attribute.userAttributeName] = attribute.value;
    }

    const localizationStore = useLocalizationStore();
    if (transformed.locale) {
      localizationStore.setUserStoredLocalization(transformed.locale);
    }
    if (transformed.plant) {
      localizationStore.setPlant(Number(transformed.plant));
    }
    if (transformed.timezone) {
      localizationStore.setPlantTimezone(transformed.timezone);
    }

    return transformed;
  }

  /**
   * Fetches user attributes from the API, sets them internally, and returns the list.
   * @returns Promise<Array<UserAttribute>> - The list of user attributes.
   */
  public async loadAttributes(): Promise<Array<UserAttribute>> {
    const userId = getUserId();
    if (userId === undefined) {
      appLogger.error('User ID not available.');
      return [];
    }

    try {
      // Fetch attributes from the API
      const attributes =
        await this.apiService.getUserAttributesByUserId(userId);

      if (attributes && Array.isArray(attributes) && attributes.length > 0) {
        return attributes;
      }
      appLogger.log('No user attributes found.');
      return [];
    } catch {
      appLogger.error('Error fetching user attributes');
      return [];
    }
  }

  /**
   * Retrieves the user's attributes as a key-value pair object.
   * @returns - An object where the keys are attribute names and the values are attribute values.
   */
  public getAttributes(): { [key: string]: string } {
    return this.userAttributes;
  }
}

