import { ref, type Ref } from 'vue';
import type { UseNpsDismissalStateOptions } from '../types';

interface UseNpsDismissalStateResult {
  cancelDialog: () => void;
  closeDialogForSession: () => void;
  resetTransientDismissal: () => void;
  transientDismissed: Ref<boolean>;
}

/**
 * Creates dismissal handlers for the runtime widget.
 * @param options The dismissal behavior dependencies and persistence callbacks.
 * @returns Dismissal helpers and the transient dismissal state.
 */
export function useNpsDismissalState(
  options: UseNpsDismissalStateOptions,
): UseNpsDismissalStateResult {
  const transientDismissed = ref(false);

  /** Resets the session-only dismissal flag. */
  function resetTransientDismissal(): void {
    transientDismissed.value = false;
  }

  /** Closes the dialog and prevents re-showing it during the current session. */
  function closeDialogForSession(): void {
    transientDismissed.value = true;
    options.closeDialog();
  }

  /** Persists dismissal metadata based on the configured dismissal behavior. */
  function cancelDialog(): void {
    const dismissedAt = new Date().toISOString();

    if (options.config.value.behaviorOnDismissal === 'REPROMPT_AFTER_DAYS') {
      options.persistState({ dismissedAt, neverReprompt: false });
    }

    if (options.config.value.behaviorOnDismissal === 'NEVER_REPROMPT') {
      options.persistState({ dismissedAt, neverReprompt: true });
    }

    if (options.config.value.behaviorOnDismissal === 'NO_SHOW_UNTIL_RELOAD') {
      options.persistState({ dismissedAt: undefined, neverReprompt: false });
    }

    closeDialogForSession();
  }

  return {
    cancelDialog,
    closeDialogForSession,
    resetTransientDismissal,
    transientDismissed,
  };
}

import { computed, ref, type ComputedRef, type Ref } from 'vue';
import type { UseNpsFormStateOptions } from '../types';

interface UseNpsFormStateResult {
  comment: Ref<string>;
  hasAttemptedSubmit: Ref<boolean>;
  isValid: ComputedRef<boolean>;
  markSubmitAttempted: () => void;
  resetForm: () => void;
  score: Ref<number | undefined>;
  selectScore: (value: number) => void;
  updateComment: (value: string) => void;
}

/**
 * Creates the local form state used by the runtime widget dialog.
 * @param options The runtime form configuration dependencies.
 * @returns The reactive score/comment state plus form helper functions.
 */
export function useNpsFormState(
  options: UseNpsFormStateOptions,
): UseNpsFormStateResult {
  const score = ref<number | undefined>(undefined);
  const comment = ref('');
  const hasAttemptedSubmit = ref(false);

  const isValid = computed(() => {
    const hasComment =
      !options.isCommentRequired.value || comment.value.trim().length > 0;

    return score.value !== undefined && hasComment;
  });

  /** Marks that the user attempted to submit the form. */
  function markSubmitAttempted(): void {
    hasAttemptedSubmit.value = true;
  }

  /** Resets the score, comment, and validation state. */
  function resetForm(): void {
    score.value = undefined;
    comment.value = '';
    hasAttemptedSubmit.value = false;
  }

  /**
   * Updates the selected score.
   * @param value The selected NPS score.
   */
  function selectScore(value: number): void {
    score.value = value;
  }

  /**
   * Updates the comment field value.
   * @param value The latest comment text.
   */
  function updateComment(value: string): void {
    comment.value = value;
  }

  return {
    comment,
    hasAttemptedSubmit,
    isValid,
    markSubmitAttempted,
    resetForm,
    score,
    selectScore,
    updateComment,
  };
}

import { computed, onBeforeUnmount, ref, watch, type ComputedRef } from 'vue';
import type {
  NpsResponseType,
  NpsShift,
  UseNpsPromptRulesOptions,
} from '../types';

const DAY_IN_MILLISECONDS = 1000 * 60 * 60 * 24;

interface UseNpsPromptRulesResult {
  canPrompt: ComputedRef<boolean>;
  dismissSuppressed: ComputedRef<boolean>;
  isEligible: ComputedRef<boolean>;
  redisplaySuppressed: ComputedRef<boolean>;
  submitSuppressed: ComputedRef<boolean>;
}

interface ResolvedResponseState {
  dismissedAt?: string;
  neverReprompt: boolean;
  responseType?: NpsResponseType;
  respondedAt?: string;
}

/**
 * Converts a date into a UTC day timestamp for calendar-day comparisons.
 * @param dateValue The date to normalize.
 * @returns The UTC day timestamp.
 */
function utcDayTimestamp(dateValue: Date): number {
  return Date.UTC(
    dateValue.getUTCFullYear(),
    dateValue.getUTCMonth(),
    dateValue.getUTCDate(),
  );
}

/**
 * Calculates whole calendar days since the supplied ISO date string.
 * @param dateValue The stored ISO date value.
 * @param currentTime
 * @returns The number of calendar days since the supplied date.
 */
function calendarDaysSince(
  dateValue: string | undefined,
  currentTime: number,
): number {
  if (!dateValue) {
    return Number.POSITIVE_INFINITY;
  }

  const parsedDate = new Date(dateValue);

  if (Number.isNaN(parsedDate.getTime())) {
    return Number.POSITIVE_INFINITY;
  }

  return Math.floor(
    (utcDayTimestamp(new Date(currentTime)) - utcDayTimestamp(parsedDate)) /
      DAY_IN_MILLISECONDS,
  );
}

/**
 * Resolves when a calendar-day-based suppression window expires.
 * @param dateValue The stored ISO date value.
 * @param waitDays The number of calendar days that must elapse.
 * @returns The unlock timestamp in milliseconds, if one can be computed.
 */
function resolveUnlockTimestamp(
  dateValue: string | undefined,
  waitDays: number | null | undefined,
): number | undefined {
  if (
    !dateValue ||
    waitDays === null ||
    waitDays === undefined ||
    waitDays < 1
  ) {
    return undefined;
  }

  const parsedDate = new Date(dateValue);

  if (Number.isNaN(parsedDate.getTime())) {
    return undefined;
  }

  return utcDayTimestamp(parsedDate) + waitDays * DAY_IN_MILLISECONDS;
}

/**
 * Resolves the response state supplied by the backend config.
 * @param options The prompt-rule dependencies.
 * @returns The backend response state.
 */
function resolveBackendResponseState(
  options: UseNpsPromptRulesOptions,
): ResolvedResponseState {
  if (!options.config.value.responseType) {
    return {
      neverReprompt: false,
    };
  }

  return {
    dismissedAt:
      options.config.value.responseType === 'DISMISSED'
        ? options.config.value.updatedAt
        : undefined,
    neverReprompt:
      options.config.value.responseType === 'DISMISSED' &&
      options.config.value.behaviorOnDismissal === 'NEVER_REPROMPT',
    responseType: options.config.value.responseType,
    respondedAt: options.config.value.updatedAt,
  };
}

/**
 * Computes whether the runtime widget is currently allowed to prompt the user.
 * @param options The runtime configuration, context, and stored state dependencies.
 * @returns Computed prompt-eligibility flags for the widget.
 */
export function useNpsPromptRules(
  options: UseNpsPromptRulesOptions,
): UseNpsPromptRulesResult {
  const currentTime = ref(Date.now());
  let promptRefreshTimer: ReturnType<typeof globalThis.setTimeout> | undefined;

  /** Clears the pending timer that re-evaluates prompt suppression. */
  function clearPromptRefreshTimer(): void {
    if (promptRefreshTimer !== undefined) {
      globalThis.clearTimeout(promptRefreshTimer);
      promptRefreshTimer = undefined;
    }
  }

  const isEligible = computed(() => {
    const allowedRoleIds = Array.isArray(options.config.value.allowedRoleIds)
      ? options.config.value.allowedRoleIds
      : [];
    const allowedShift: Array<NpsShift> = Array.isArray(
      options.config.value.allowedShift,
    )
      ? options.config.value.allowedShift
      : ['ALL'];
    const roleAllowed =
      allowedRoleIds.length === 0 ||
      (options.context.value.roleId
        ? allowedRoleIds.includes(options.context.value.roleId)
        : false);
    const shiftAllowed =
      allowedShift.length === 0 ||
      allowedShift.includes('ALL') ||
      (options.context.value.shift
        ? allowedShift.includes(options.context.value.shift)
        : false);

    return roleAllowed && shiftAllowed;
  });

  const submitSuppressed = computed(() => {
    const effectiveResponseState = resolveBackendResponseState(options);

    if (options.config.value.isForced) {
      return false;
    }

    if (options.config.value.redisplayInterval === 'CUSTOM') {
      return false;
    }

    return effectiveResponseState.responseType === 'SUBMITTED';
  });

  const redisplaySuppressed = computed(() => {
    const evaluationTime = currentTime.value;
    const effectiveResponseState = resolveBackendResponseState(options);

    if (options.config.value.isForced) {
      return false;
    }

    if (options.config.value.redisplayInterval !== 'CUSTOM') {
      return false;
    }

    if (effectiveResponseState.responseType !== 'SUBMITTED') {
      return false;
    }

    const elapsedDays = calendarDaysSince(
      effectiveResponseState.respondedAt,
      evaluationTime,
    );

    return (
      Number.isFinite(elapsedDays) &&
      elapsedDays < (options.config.value.customRedisplayDays ?? 0)
    );
  });

  const dismissSuppressed = computed(() => {
    const evaluationTime = currentTime.value;
    const effectiveResponseState = resolveBackendResponseState(options);

    if (options.config.value.isForced) {
      return false;
    }

    if (effectiveResponseState.responseType !== 'DISMISSED') {
      return false;
    }

    if (options.config.value.behaviorOnDismissal === 'NO_SHOW_UNTIL_RELOAD') {
      return options.transientDismissed.value;
    }

    if (effectiveResponseState.neverReprompt) {
      return true;
    }

    if (options.config.value.behaviorOnDismissal === 'REPROMPT_AFTER_DAYS') {
      if (!effectiveResponseState.dismissedAt) {
        return false;
      }

      const repromptDay = options.config.value.repromptDay ?? 0;

      if (repromptDay < 1) {
        return false;
      }

      const elapsedDays = calendarDaysSince(
        effectiveResponseState.dismissedAt,
        evaluationTime,
      );

      return Number.isFinite(elapsedDays) && elapsedDays < repromptDay;
    }

    return false;
  });

  const nextPromptRefreshAt = computed(() => {
    const scheduledRefreshes: Array<number> = [];
    const effectiveResponseState = resolveBackendResponseState(options);

    if (options.config.value.isForced) {
      return;
    }

    if (
      options.config.value.redisplayInterval === 'CUSTOM' &&
      effectiveResponseState.responseType === 'SUBMITTED'
    ) {
      const responseUnlockTimestamp = resolveUnlockTimestamp(
        effectiveResponseState.respondedAt,
        options.config.value.customRedisplayDays,
      );

      if (
        responseUnlockTimestamp !== undefined &&
        responseUnlockTimestamp > currentTime.value
      ) {
        scheduledRefreshes.push(responseUnlockTimestamp);
      }

      return scheduledRefreshes.length > 0
        ? Math.min(...scheduledRefreshes)
        : undefined;
    }

    if (effectiveResponseState.responseType !== 'DISMISSED') {
      return scheduledRefreshes.length > 0
        ? Math.min(...scheduledRefreshes)
        : undefined;
    }

    if (effectiveResponseState.neverReprompt) {
      return scheduledRefreshes.length > 0
        ? Math.min(...scheduledRefreshes)
        : undefined;
    }

    if (options.config.value.behaviorOnDismissal === 'REPROMPT_AFTER_DAYS') {
      const dismissUnlockTimestamp = resolveUnlockTimestamp(
        effectiveResponseState.dismissedAt,
        options.config.value.repromptDay,
      );

      if (
        dismissUnlockTimestamp !== undefined &&
        dismissUnlockTimestamp > currentTime.value
      ) {
        scheduledRefreshes.push(dismissUnlockTimestamp);
      }
    }

    return scheduledRefreshes.length > 0
      ? Math.min(...scheduledRefreshes)
      : undefined;
  });

  const canPrompt = computed(
    () =>
      options.config.value.isActive &&
      isEligible.value &&
      !redisplaySuppressed.value &&
      !submitSuppressed.value &&
      !dismissSuppressed.value,
  );

  watch(
    nextPromptRefreshAt,
    (nextPromptRefreshTime) => {
      clearPromptRefreshTimer();

      if (nextPromptRefreshTime === undefined) {
        return;
      }

      promptRefreshTimer = globalThis.setTimeout(
        () => {
          currentTime.value = Date.now();
        },
        Math.max(nextPromptRefreshTime - Date.now(), 0),
      );
    },
    { immediate: true },
  );

  onBeforeUnmount(() => {
    clearPromptRefreshTimer();
  });

  return {
    canPrompt,
    dismissSuppressed,
    isEligible,
    redisplaySuppressed,
    submitSuppressed,
  };
}

import { ref, type Ref } from 'vue';
import type { NpsWidgetStoredState, UseNpsStoredStateOptions } from '../types';

interface UseNpsStoredStateResult {
  persistState: (nextState: Partial<NpsWidgetStoredState>) => void;
  readStoredState: () => void;
  storedState: Ref<NpsWidgetStoredState>;
}

/**
 * Builds a local-storage key for the runtime widget.
 * @param segments The key segments to join.
 * @returns A colon-delimited storage key.
 */
export function buildNpsStorageKey(
  ...segments: Array<string | undefined>
): string {
  return segments
    .map((segment) => (segment?.trim().length ? segment.trim() : 'global'))
    .join(':');
}

/**
 * Normalizes parsed storage data into a widget-state object.
 * @param value The parsed value loaded from local storage.
 * @returns A normalized widget-state object.
 */
function normalizeStoredState(value: unknown): NpsWidgetStoredState {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return {};
  }

  const storedState = value as Record<string, unknown>;

  return {
    dismissedAt:
      typeof storedState.dismissedAt === 'string'
        ? storedState.dismissedAt
        : undefined,
    lastResponseType:
      storedState.lastResponseType === 'SUBMITTED' ||
      storedState.lastResponseType === 'DISMISSED'
        ? storedState.lastResponseType
        : undefined,
    lastSubmittedAt:
      typeof storedState.lastSubmittedAt === 'string'
        ? storedState.lastSubmittedAt
        : undefined,
    neverReprompt:
      typeof storedState.neverReprompt === 'boolean'
        ? storedState.neverReprompt
        : undefined,
    releaseVersion:
      typeof storedState.releaseVersion === 'string'
        ? storedState.releaseVersion
        : undefined,
  };
}

/**
 * Builds the stored metadata that tracks release changes.
 * @param options The storage dependencies for the widget.
 * @returns The normalized metadata subset persisted for the widget.
 */
function buildMetadataState(
  options: UseNpsStoredStateOptions,
): Pick<NpsWidgetStoredState, 'releaseVersion'> {
  return {
    releaseVersion: options.releaseVersion.value,
  };
}

/**
 * Determines whether stored state should be cleared for a new release.
 * @param previousReleaseVersion The persisted release version.
 * @param nextReleaseVersion The current runtime release version.
 * @returns True when a new concrete release version supersedes the stored one.
 */
function shouldResetForRelease(
  previousReleaseVersion: string | undefined,
  nextReleaseVersion: string | undefined,
): boolean {
  const normalizedNextReleaseVersion = nextReleaseVersion?.trim();

  if (!normalizedNextReleaseVersion) {
    return false;
  }

  return previousReleaseVersion?.trim() !== normalizedNextReleaseVersion;
}

/**
 * Creates the persistence layer used by the runtime widget.
 * @param options The storage dependencies for the widget.
 * @returns Reactive storage state plus read and persist helpers.
 */
export function useNpsStoredState(
  options: UseNpsStoredStateOptions,
): UseNpsStoredStateResult {
  const storedState = ref<NpsWidgetStoredState>({});

  /** Persists the current normalized state to local storage. */
  function writeStoredState(): void {
    globalThis.localStorage.setItem(
      options.storageKey.value,
      JSON.stringify(storedState.value),
    );
  }

  /** Reads the stored widget state and resets it when the release changes. */
  function readStoredState(): void {
    const metadataState = buildMetadataState(options);
    let nextStoredState: NpsWidgetStoredState;

    try {
      const rawState = globalThis.localStorage.getItem(
        options.storageKey.value,
      );
      nextStoredState = normalizeStoredState(
        rawState ? JSON.parse(rawState) : undefined,
      );
    } catch {
      nextStoredState = {};
    }

    if (
      shouldResetForRelease(
        nextStoredState.releaseVersion,
        metadataState.releaseVersion,
      )
    ) {
      storedState.value = {
        ...metadataState,
      };

      options.onResetState?.();
    } else {
      storedState.value = {
        ...nextStoredState,
        ...metadataState,
      };
    }

    writeStoredState();
  }

  /**
   * Persists the next partial state for the runtime widget.
   * @param nextState The partial widget state to merge and persist.
   */
  function persistState(nextState: Partial<NpsWidgetStoredState>): void {
    storedState.value = {
      ...storedState.value,
      ...nextState,
      ...buildMetadataState(options),
    };

    writeStoredState();
  }

  return {
    persistState,
    readStoredState,
    storedState,
  };
}

import { computed, ref, watch, type ComputedRef, type Ref } from 'vue';
import type {
  NpsResponseDraft,
  NpsWidgetStoredState,
  UseNpsWidgetStateOptions,
} from '../types';
import { useNpsDismissalState } from './use-nps-dismissal-state';
import { useNpsFormState } from './use-nps-form-state';
import { useNpsPromptRules } from './use-nps-prompt-rules';
import { buildNpsStorageKey, useNpsStoredState } from './use-nps-stored-state';

const STORAGE_PREFIX = 'mesx:nps';

interface UseNpsWidgetStateResult {
  cancelDialog: () => void;
  closeDialog: () => void;
  closeDialogForSession: () => void;
  comment: Ref<string>;
  completeDismissal: () => NpsResponseDraft;
  completeSubmission: () => NpsResponseDraft | undefined;
  hasAttemptedSubmit: Ref<boolean>;
  isButtonVisible: Ref<boolean>;
  isDialogOpen: Ref<boolean>;
  isValid: ComputedRef<boolean>;
  openDialog: () => void;
  openDialogFromButton: () => void;
  score: Ref<number | undefined>;
  selectScore: (value: number) => void;
  syncVisibility: () => void;
  updateComment: (value: string) => void;
}

/** Reusable no-op helper used for deferred function wiring. */
function noop(): void {}

/** Reusable no-op persistence helper used before real storage wiring exists. */
function noopPersistState(): void {}

/**
 * Creates the runtime widget state and all dialog/drag interaction helpers.
 * @param options The runtime widget dependencies.
 * @returns Reactive widget state and helper functions for the floating survey.
 */
export function useNpsWidgetState(
  options: UseNpsWidgetStateOptions,
): UseNpsWidgetStateResult {
  const isDialogOpen = ref(false);
  const isButtonVisible = ref(false);
  const lastEventSeed = ref(options.eventSeed.value);
  let triggerTimer: ReturnType<typeof globalThis.setTimeout> | undefined;
  let syncVisibility: (closeBlockedDialog?: boolean) => void = noop;
  let resetTransientDismissal: () => void = noop;
  let persistState: (nextState: Partial<NpsWidgetStoredState>) => void =
    noopPersistState;
  const currentReleaseVersion = computed(
    () =>
      options.config.value.releaseVersion ||
      options.context.value.releaseVersion,
  );

  const storageKey = computed(() =>
    buildNpsStorageKey(
      STORAGE_PREFIX,
      options.config.value.appId,
      options.config.value.id,
      options.context.value.userId,
      options.context.value.roleId,
    ),
  );
  const {
    comment,
    hasAttemptedSubmit,
    isValid,
    markSubmitAttempted,
    resetForm,
    score,
    selectScore,
    updateComment,
  } = useNpsFormState({
    isCommentRequired: computed(() => options.config.value.isCommentRequired),
  });

  /** Closes the dialog and resynchronizes the floating button visibility. */
  function closeDialog(): void {
    isDialogOpen.value = false;
    syncVisibility();
  }

  const storedStateApi = useNpsStoredState({
    onResetState: () => {
      resetTransientDismissal();
    },
    releaseVersion: currentReleaseVersion,
    storageKey,
  });
  persistState = storedStateApi.persistState;

  const { readStoredState, storedState } = storedStateApi;
  const {
    cancelDialog,
    closeDialogForSession,
    resetTransientDismissal: nextResetTransientDismissal,
    transientDismissed,
  } = useNpsDismissalState({
    closeDialog,
    config: options.config,
    persistState,
  });
  resetTransientDismissal = nextResetTransientDismissal;
  const { canPrompt, isEligible, submitSuppressed } = useNpsPromptRules({
    config: options.config,
    context: options.context,
    storedState,
    transientDismissed,
  });
  const canOpenFromButton = computed(
    () =>
      options.config.value.isActive &&
      options.config.value.showFloatingButton &&
      isEligible.value &&
      !submitSuppressed.value,
  );

  /**
   * Syncs button visibility to the current prompt and dialog state.
   * @param closeBlockedDialog
   */
  syncVisibility = (closeBlockedDialog = true): void => {
    // Hide floating button if NPS is submitted or responseType is 'SUBMITTED'
    isButtonVisible.value =
      options.config.value.isActive &&
      options.config.value.showFloatingButton &&
      isEligible.value &&
      !submitSuppressed.value &&
      options.config.value.responseType !== 'SUBMITTED';

    if (closeBlockedDialog && !canPrompt.value) {
      isDialogOpen.value = false;
    }
  };

  /** Clears any scheduled time-based runtime trigger. */
  function clearTriggerTimer(): void {
    if (triggerTimer !== undefined) {
      globalThis.clearTimeout(triggerTimer);
      triggerTimer = undefined;
    }
  }

  /** Opens the runtime dialog when prompting is currently allowed. */
  function openDialog(): void {
    if (!canPrompt.value) {
      syncVisibility();
      return;
    }

    isDialogOpen.value = true;
    syncVisibility();
  }

  /** Opens the dialog from the floating button without applying dismissal suppression. */
  function openDialogFromButton(): void {
    if (!canOpenFromButton.value) {
      syncVisibility();
      return;
    }

    isDialogOpen.value = true;
    syncVisibility(false);
  }

  /** Schedules the next time-based prompt when configured. */
  function scheduleTimeTrigger(): void {
    clearTriggerTimer();

    if (options.config.value.triggerType !== 'TIME_BASED' || !canPrompt.value) {
      syncVisibility();
      return;
    }

    const delay =
      Math.max(options.config.value.triggerDelaySeconds ?? 0, 0) * 1000;
    triggerTimer = globalThis.setTimeout(() => {
      openDialog();
    }, delay);
  }

  /**
   * Builds the runtime response draft for the supplied response type.
   * @param responseType The response type to encode in the draft.
   * @returns The normalized runtime response draft.
   */
  function buildResponseDraft(
    responseType: NpsResponseDraft['responseType'],
  ): NpsResponseDraft {
    return {
      comment: responseType === 'SUBMITTED' ? comment.value.trim() : null,
      configurationId: options.config.value.id,
      plantId: options.context.value.plantId,
      releaseVersion:
        options.context.value.releaseVersion ??
        options.config.value.releaseVersion,
      responseDate: new Date().toISOString(),
      responseType,
      roleId: options.context.value.roleId,
      score: responseType === 'SUBMITTED' ? (score.value ?? null) : null,
      shift: options.context.value.shift,
      userId: options.context.value.userId,
    };
  }

  /**
   * Completes a submit interaction when the current form state is valid.
   * @returns The submitted runtime draft when validation passes.
   */
  function completeSubmission(): NpsResponseDraft | undefined {
    markSubmitAttempted();

    if (!isValid.value || score.value === undefined) {
      return undefined;
    }

    persistState({
      dismissedAt: undefined,
      lastSubmittedAt: new Date().toISOString(),
      lastResponseType: 'SUBMITTED',
      neverReprompt: false,
    });

    isDialogOpen.value = false;
    syncVisibility();

    const payload = buildResponseDraft('SUBMITTED');
    resetForm();
    return payload;
  }

  /**
   * Completes a dismiss interaction and resets the transient form state.
   * @returns The dismissal runtime draft.
   */
  function completeDismissal(): NpsResponseDraft {
    cancelDialog();
    persistState({ lastResponseType: 'DISMISSED' });
    const payload = buildResponseDraft('DISMISSED');
    resetForm();
    return payload;
  }

  watch(
    () => options.config.value,
    () => {
      readStoredState();
      if (options.config.value.isForced && canPrompt.value) {
        openDialog();
        return;
      }

      scheduleTimeTrigger();
      syncVisibility();
    },
    { deep: true, immediate: true },
  );

  watch(
    () => [storageKey.value, currentReleaseVersion.value],
    () => {
      readStoredState();
      scheduleTimeTrigger();
      syncVisibility();
    },
    { immediate: true },
  );

  watch(
    () => options.eventSeed.value,
    (nextSeed) => {
      if (
        options.config.value.triggerType === 'EVENT_BASED' &&
        nextSeed !== undefined &&
        nextSeed !== undefined &&
        nextSeed !== lastEventSeed.value &&
        canPrompt.value
      ) {
        openDialog();
      }

      lastEventSeed.value = nextSeed;
    },
  );

  watch(canPrompt, () => {
    scheduleTimeTrigger();
    syncVisibility();
  });

  return {
    cancelDialog,
    closeDialog,
    closeDialogForSession,
    comment,
    completeDismissal,
    completeSubmission,
    hasAttemptedSubmit,
    isButtonVisible,
    isDialogOpen,
    isValid,
    openDialog,
    openDialogFromButton,
    score,
    selectScore,
    syncVisibility,
    updateComment,
  };
}

import { computed, ref, watch, type ComputedRef, type Ref } from 'vue';
import { getRuntimeNpsConfiguration } from '../services/nps-api';
import type {
  NpsBackendConfigDto,
  NpsConfiguration,
  UseRuntimeNpsConfigurationOptions,
} from '../types';
import {
  normalizeRuntimeConfiguration,
  normalizeRuntimeRoleNames,
  resolveRuntimeAppName,
} from '../utils/nps-runtime-helpers';

interface UseRuntimeNpsConfigurationResult {
  currentAppName: ComputedRef<string>;
  matchedRoleName: Ref<string | undefined>;
  refreshRuntimeConfiguration: () => Promise<void>;
  resolvedConfiguration: ComputedRef<NpsConfiguration | undefined>;
  runtimeConfiguration: Ref<NpsBackendConfigDto | undefined>;
}

/**
 * Loads and normalizes the runtime NPS configuration for the current app context.
 * @param options The runtime configuration inputs and callback hooks.
 * @returns The current app name, resolved configuration, and matched role name.
 */
export function useRuntimeNpsConfiguration(
  options: UseRuntimeNpsConfigurationOptions,
): UseRuntimeNpsConfigurationResult {
  const runtimeConfiguration = ref<NpsBackendConfigDto | undefined>(undefined);
  const hasLoadedRuntimeConfiguration = ref(false);
  const lastRequestId = ref(0);
  const matchedRoleName = ref<string | undefined>(undefined);
  const currentAppName = computed<string>(() =>
    resolveRuntimeAppName(options.appName.value),
  );

  const roleNames = computed(() =>
    normalizeRuntimeRoleNames(options.roleName.value),
  );

  const canLoadRuntimeConfiguration = computed(
    () =>
      options.configuration.value === undefined &&
      options.enabled.value &&
      Boolean(
        options.adminBaseUrl.value &&
          currentAppName.value &&
          roleNames.value.length > 0 &&
          options.currentUserId.value !== undefined,
      ),
  );

  const runtimeConfigurationKey = computed(() =>
    [
      options.adminBaseUrl.value,
      currentAppName.value,
      roleNames.value.join('|'),
      String(options.currentUserId.value ?? ''),
    ].join('::'),
  );

  const resolvedConfiguration = computed<NpsConfiguration | undefined>(() => {
    if (options.configuration.value) {
      return options.configuration.value;
    }

    return runtimeConfiguration.value
      ? normalizeRuntimeConfiguration(runtimeConfiguration.value, {
          fallbackAppName: currentAppName.value,
          modalContent: options.modalContent.value,
          releaseVersion: options.releaseVersion.value,
        })
      : undefined;
  });

  /** Loads the runtime configuration for the current app and matched role. */
  async function loadRuntimeConfiguration(): Promise<void> {
    if (!canLoadRuntimeConfiguration.value) {
      runtimeConfiguration.value = undefined;
      hasLoadedRuntimeConfiguration.value = false;
      matchedRoleName.value = undefined;
      return;
    }

    if (hasLoadedRuntimeConfiguration.value && runtimeConfiguration.value) {
      return;
    }

    const nextRequestId = lastRequestId.value + 1;
    lastRequestId.value = nextRequestId;
    matchedRoleName.value = undefined;

    try {
      const config = await getRuntimeNpsConfiguration({
        accessToken: options.accessToken.value ?? undefined,
        adminBaseUrl: options.adminBaseUrl.value,
        appName: currentAppName.value,
        roleNames: roleNames.value,
        userId: options.currentUserId.value ?? 0,
      });

      if (lastRequestId.value !== nextRequestId) {
        return;
      }

      runtimeConfiguration.value = config || undefined;
      hasLoadedRuntimeConfiguration.value = true;

      // Optionally, set matchedRoleName if config is present and you can infer which role matched (if backend returns info)
      if (config) {
        options.onConfigLoaded?.(config);
        // MatchedRoleName.value = ... // Set if backend returns matched role
      }
    } catch (error) {
      if (lastRequestId.value !== nextRequestId) {
        return;
      }

      runtimeConfiguration.value = undefined;
      hasLoadedRuntimeConfiguration.value = false;
      options.onConfigError?.(error);
    }
  }

  /** Reloads runtime configuration after a response mutates backend state. */
  async function refreshRuntimeConfiguration(): Promise<void> {
    hasLoadedRuntimeConfiguration.value = false;
    await loadRuntimeConfiguration();
  }

  watch(
    () => [
      options.configuration.value,
      options.enabled.value,
      options.accessToken.value,
      options.adminBaseUrl.value,
      currentAppName.value,
      runtimeConfigurationKey.value,
      roleNames.value.join('|'),
      options.currentUserId.value,
    ],
    async () => {
      await refreshRuntimeConfiguration();
    },
    { immediate: true },
  );

  return {
    currentAppName,
    matchedRoleName,
    refreshRuntimeConfiguration,
    resolvedConfiguration,
    runtimeConfiguration,
  };
}

