import axios from 'axios';
import type { NpsBackendConfigDto, NpsBackendResponseDto } from '../types';

interface GetRuntimeNpsConfigurationOptions {
  accessToken?: string;
  adminBaseUrl: string;
  appName: string;
  roleNames: Array<string>;
  userId: number;
}

interface CreateRuntimeNpsResponseOptions {
  accessToken?: string;
  adminBaseUrl: string;
  payload: NpsBackendResponseDto;
}

/**
 * Normalizes a backend base URL by trimming trailing slashes.
 * @param baseUrl The runtime admin backend base URL.
 * @returns The normalized base URL.
 */
function normalizeBaseUrl(baseUrl: string): string {
  return baseUrl.trim().replace(/\/+$/u, '');
}

/**
 * Builds authenticated request headers for the runtime API.
 * @param accessToken The optional bearer token used for runtime requests.
 * @returns The HTTP headers for the outgoing request.
 */
function getHeaders(accessToken?: string): Record<string, string> {
  const trimmedToken = accessToken?.trim();

  if (!trimmedToken) {
    return {};
  }

  return {
    authorization: trimmedToken.toLowerCase().startsWith('bearer ')
      ? trimmedToken
      : `Bearer ${trimmedToken}`,
  };
}

/**
 * Loads the runtime NPS configuration for a specific app, role, and user.
 * @param options The request inputs for the runtime configuration API.
 * @returns The backend runtime configuration when the request succeeds.
 */
export async function getRuntimeNpsConfiguration(
  options: GetRuntimeNpsConfigurationOptions,
): Promise<NpsBackendConfigDto | null> {
  const requestUrl = `${normalizeBaseUrl(options.adminBaseUrl)}/nps-config/get-nps-by-role-name/${encodeURIComponent(options.appName)}/${encodeURIComponent(String(options.userId))}`;

  const response = await axios.post<NpsBackendConfigDto | null>(
    requestUrl,
    { roleNames: options.roleNames },
    { headers: getHeaders(options.accessToken) },
  );

  return response.data;
}

/**
 * Posts a runtime NPS response to the backend service.
 * @param options The runtime response request inputs.
 */
export async function createRuntimeNpsResponse(
  options: CreateRuntimeNpsResponseOptions,
): Promise<void> {
  const requestUrl = `${normalizeBaseUrl(options.adminBaseUrl)}/nps-response/create-response`;

  await axios.post(requestUrl, options.payload, {
    headers: getHeaders(options.accessToken),
  });
}

