export const NPS_RUNTIME_MODAL_TITLE = 'How would you evaluate this screen?';
export const NPS_RUNTIME_MODAL_DESCRIPTION =
  'This will help us improve your experience.';

import type {
  NormalizeRuntimeConfigurationOptions,
  NpsBackendConfigDto,
  NpsConfiguration,
  NpsDismissalBehavior,
  NpsResponseType,
  NpsTriggerType,
  NumericInput,
} from '../types';

/**
 * Parses an optional positive numeric input.
 * @param value The numeric input from runtime configuration or context.
 * @returns The parsed positive number when valid.
 */
export function parsePositiveNumber(value: NumericInput): number | undefined {
  if (value === null || value === undefined || value === '') {
    return undefined;
  }

  const parsedValue =
    typeof value === 'number' ? value : Number.parseInt(value, 10);

  if (Number.isNaN(parsedValue) || parsedValue < 0) {
    return undefined;
  }

  return parsedValue;
}

/**
 * Parses a required positive integer from runtime input.
 * @param value The numeric input from runtime configuration or context.
 * @returns The parsed positive integer when valid.
 */
export function parseRequiredPositiveInteger(
  value: NumericInput,
): number | undefined {
  const parsedValue = parsePositiveNumber(value);

  if (parsedValue === undefined || parsedValue <= 0) {
    return undefined;
  }

  return parsedValue;
}

/**
 * Normalizes the backend dismissal behavior into the runtime enum.
 * @param value The backend dismissal behavior value.
 * @returns The normalized runtime dismissal behavior.
 */
export function normalizeDismissalBehavior(
  value: NumericInput,
): NpsDismissalBehavior {
  if (typeof value === 'string') {
    const normalizedValue = value.trim().toUpperCase();

    if (normalizedValue === 'NEVER_REPROMPT' || normalizedValue === '2') {
      return 'NEVER_REPROMPT';
    }

    if (
      normalizedValue === 'REPROMPT_AFTER_DAYS' ||
      normalizedValue === 'REPROMPT_AFTER_DATE' ||
      normalizedValue === '1'
    ) {
      return 'REPROMPT_AFTER_DAYS';
    }
  }

  if (value === 2) {
    return 'NEVER_REPROMPT';
  }

  if (value === 1) {
    return 'REPROMPT_AFTER_DAYS';
  }

  return 'NO_SHOW_UNTIL_RELOAD';
}

/**
 * Normalizes the backend trigger type into the runtime enum.
 * @param value The backend trigger type value.
 * @returns The normalized runtime trigger type.
 */
export function normalizeTriggerType(
  value: string | null | undefined,
): NpsTriggerType {
  const normalizedValue = value?.trim().toUpperCase();

  if (normalizedValue === 'EVENT_BASED' || normalizedValue === 'MANUAL') {
    return normalizedValue;
  }

  return 'TIME_BASED';
}

/**
 * Normalizes the backend response type into the runtime enum.
 * @param value The backend response type value.
 * @returns The normalized runtime response type.
 */
export function normalizeResponseType(
  value: string | null | undefined,
): NpsResponseType | undefined {
  const normalizedValue = value?.trim().toUpperCase();

  if (normalizedValue === 'SUBMITTED' || normalizedValue === 'DISMISSED') {
    return normalizedValue;
  }

  return undefined;
}

/**
 * Maps an NPS score to the standard user category label.
 * @param score The submitted NPS score.
 * @returns The runtime category label for the score.
 */
export function getUserCategory(score: number): string {
  if (score >= 9) {
    return 'Promoter';
  }

  if (score >= 7) {
    return 'Passive';
  }

  return 'Detractor';
}

/**
 * Normalizes runtime role-name input into a flat string array.
 * @param value The configured runtime role value.
 * @returns The normalized role-name array.
 */
export function normalizeRuntimeRoleNames(
  value: string | Array<string> | undefined,
): Array<string> {
  if (Array.isArray(value)) {
    return value.filter(
      (roleName): roleName is string => roleName.trim().length > 0,
    );
  }

  if (typeof value === 'string' && value.trim()) {
    return value
      .split('|')
      .map((roleName) => roleName.trim())
      .filter((roleName) => roleName.length > 0);
  }

  return [];
}

/**
 * Resolves the runtime app name from explicit input, route meta, or pathname.
 * @param options The runtime app-name resolution inputs.
 * @returns The resolved application identifier.
 */

/**
 *
 * @param appName
 */
export function resolveRuntimeAppName(appName: string | undefined): string {
  return appName?.trim() || 'UNKNOWN';
}

/**
 * Normalizes backend configuration into the runtime NPS configuration shape.
 * @param config The backend NPS configuration payload.
 * @param options The fallback runtime normalization options.
 * @returns The normalized runtime NPS configuration.
 */
export function normalizeRuntimeConfiguration(
  config: NpsBackendConfigDto,
  options: NormalizeRuntimeConfigurationOptions,
): NpsConfiguration {
  const redisplayDays = parsePositiveNumber(config.redisplayInterval);
  const updatedAt = config.updatedAt ?? new Date().toISOString();
  const roleNames =
    config.roleNames?.filter(
      (roleName): roleName is string => roleName.trim().length > 0,
    ) ?? [];
  let allowedRoleIds = roleNames;

  if (allowedRoleIds.length === 0) {
    const fallbackRoleName = config.roleName?.trim();

    if (fallbackRoleName) {
      allowedRoleIds = [fallbackRoleName];
    }
  }

  return {
    allowedRoleIds,
    allowedShift: ['ALL'],
    appId: config.appName?.trim() || options.fallbackAppName || 'MESX',
    behaviorOnDismissal: normalizeDismissalBehavior(config.behaviorDismissal),
    createdAt: updatedAt,
    customRedisplayDays: redisplayDays ?? null,
    id: String(config.npsId),
    isActive: config.isActive,
    isCommentRequired: config.commentRequired,
    isForced: false,
    modalContent: options.modalContent,
    recordUntil: null,
    redisplayInterval: redisplayDays && redisplayDays > 0 ? 'CUSTOM' : 'NEVER',
    releaseVersion: config.releaseId?.trim() || options.releaseVersion || '',
    repromptDay: parsePositiveNumber(config.repromptDay) ?? null,
