export const NotifyPlugin = {
  install: (app: App, options: { $q: QuasarPluginOptions }) => {
    // Retrieve the Quasar instance
    const $q = options?.$q as QuasarNotify; // Explicitly cast $q to QuasarNotify

    console.log('Quasar instance:', $q);
    if (!$q || typeof $q.notify !== 'function') {
      console.error(
        'Quasar instance ($q) is not valid or does not provide a notify method.',
      );
      return;
    }

    // Pass $q to useNotify to create the notification functions
    const notify = useNotify($q);

    // Add to global properties
    app.config.globalProperties.$notify = notify;

    // Add to provide/inject API
    app.provide('notify', notify);
  },
};

