import { createApp, h } from 'vue';
import type {
  QuasarNotifyLike,
  ToastApi,
  ToastOptions,
  ToastRenderProps as ToastRenderProperties,
} from '../../ui/types/toast';
import Toast from './Toast.vue';

export type {
  QuasarNotifyLike,
  ToastApi,
  ToastOptions,
  ToastRenderProps,
} from '../../ui/types/toast';

export const renderToastHtml = (properties: ToastRenderProperties): string => {
  if (typeof document === 'undefined') return '';

  const container = document.createElement('div');
  const app = createApp({
    render: () => h(Toast as any, properties as any),
  });

  app.mount(container);
  const html = container.innerHTML;
  app.unmount();

  return html;
};

export const showToast = (
  $q: QuasarNotifyLike,
  options: ToastOptions = {},
): void => {
  showToastInternal($q, options);
};

export const createToast = ($q: QuasarNotifyLike): ToastApi => {
  return {
    show: (options?: ToastOptions) => showToast($q, options ?? {}),
  };
};

interface ActiveToast {
  close: () => void;
  toastId: string;
}

const activeToastsByDedupeKey = new Map<string, ActiveToast>();

const showToastInternal = (
  $q: QuasarNotifyLike,
  options: ToastOptions,
): void => {
  if (typeof document === 'undefined') return;

  const {
    timeoutSeconds,
    position = 'bottom-right',
    title = '',
    message = '',
    icon = 'info',
    countdownLabel = 'This notification closes in',
    closable = true,
    group = 'mesx-toast',
    id,
    dedupeKey,
    dedupeStrategy = 'replace',
  } = options;

  const effectiveDedupeKey = dedupeKey ?? id;
  if (effectiveDedupeKey) {
    const existing = activeToastsByDedupeKey.get(effectiveDedupeKey);
    if (existing) {
      if (dedupeStrategy === 'ignore') return;
      existing.close();
      activeToastsByDedupeKey.delete(effectiveDedupeKey);
    }
  }

  const isSticky = timeoutSeconds === 0 || timeoutSeconds === null;
  const effectiveClosable = isSticky ? true : closable;

  const toastId = id
    ? `mesx-toast-${id}`
    : `mesx-toast-${Math.random().toString(36).slice(2)}`;
  let remaining = isSticky ? 0 : Math.max(1, Math.floor(timeoutSeconds ?? 5));
  let intervalId: ReturnType<typeof setInterval> | undefined;
  let isClosed = false;
  let dismissFromNotify: (() => void) | undefined;

  const html = renderToastHtml({
    toastId,
    title,
    message,
    icon,
    countdownSeconds: isSticky ? undefined : remaining,
    countdownLabel,
    closable: effectiveClosable,
  });

  const cleanup = (): void => {
    document.removeEventListener('click', handleCloseClick);
    if (intervalId) clearInterval(intervalId);

    if (effectiveDedupeKey) {
      const active = activeToastsByDedupeKey.get(effectiveDedupeKey);
      if (active?.toastId === toastId) {
        activeToastsByDedupeKey.delete(effectiveDedupeKey);
      }
    }
  };

  const close = (): void => {
    if (isClosed) return;
    isClosed = true;

    if (dismissFromNotify) {
      dismissFromNotify();
      return;
    }

    cleanup();
    const root = document.querySelector(`[data-mesx-toast-id="${toastId}"]`);
    if (root) root.remove();
  };

  /**
   *
   * @param event
   */
  function handleCloseClick(event: Event): void {
    const { target } = event;
    if (!(target instanceof Element)) return;

    const closeButton = target.closest('[data-mesx-toast-close]');
    if (!closeButton) return;

    const root = closeButton.closest(`[data-mesx-toast-id="${toastId}"]`);
    if (!root) return;

    close();
  }

  document.addEventListener('click', handleCloseClick);

  if (effectiveDedupeKey) {
    activeToastsByDedupeKey.set(effectiveDedupeKey, { close, toastId });
  }

  const notifyResult = $q.notify({
    group,
    html: true,
    position,
    badgePosition: 'bottom-right',
    badgeClass: 'mesx-toast-notify-group-badge',
    timeout: isSticky ? 0 : remaining * 1000,
    message: html,
    onDismiss: () => {
      cleanup();
    },
  });

  const notifyAny: any = notifyResult;
  if (typeof notifyAny === 'function') {
    dismissFromNotify = notifyAny;
  } else if (notifyAny && typeof notifyAny.dismiss === 'function') {
    dismissFromNotify = () => notifyAny.dismiss();
  }

  if (!isSticky) {
    intervalId = setInterval(() => {
      remaining -= 1;
      const element = document.querySelector(
        `[data-mesx-toast-id="${toastId}"] [data-mesx-toast-countdown]`,
      );
      if (element) element.textContent = String(Math.max(0, remaining));
      if (remaining <= 0) {
        clearInterval(intervalId);
      }
    }, 1000);
  }
};

