import axios from 'axios';
import { useLocalizationStore } from '../store/localization-store.ts';
import { MenuList } from '../types/menu-list.ts';

class ApiService {
  private readonly umeBackend: string;

  private readonly token: string;

  public getPlantLink = async (plant: number): Promise<string | undefined> => {
    try {
      const response = await axios.get(
        `${this.umeBackend}/downtime/getPlantLink/${plant}`,
        {
          headers: {
            authorization: `Bearer ${this.token}`,
          },
        },
      );
      return response.data;
    } catch (error) {
      console.error('Error fetching support URL from backend:', error);
      return undefined;
    }
  };

  public fetchSupportUrlFromBackend = async (
    path: string,
  ): Promise<string | null> => {
    try {
      const encodedPath = encodeURIComponent(path);
      const response = await axios.get<{ supportUrl: string | null }>(
        `${this.umeBackend}/app-page-list/find-support-url?path=${encodedPath}`,
        {
          headers: {
            authorization: `Bearer ${this.token}`,
          },
        },
      );
      return response.data.supportUrl ?? null;
    } catch (error) {
      console.error('Error fetching support URL from backend:', error);
      return null;
    }
  };

  constructor(umeBackend: string, token: string) {
    this.umeBackend = umeBackend;
    this.token = token;
  }

  /**
   * Fetches favorite screen IDs for the current user from the backend.
   * @returns Array of favorite screen IDs.
   */
  public async fetchFavoriteScreens(): Promise<Array<string | number>> {
    const userId = localStorage.getItem('userId');
    const { plant } = useLocalizationStore();
    if (!userId || !plant) return [];
    try {
      const url = `${this.umeBackend}/user-preference/${plant}/${userId}/FAVORITES`;
      const response = await axios.get(url, {
        headers: { authorization: `Bearer ${this.token}` },
      });
      if (response.data.length > 0 && response.data[0].userCriteria) {
        // Parse as IDs (number if possible, else string)
        return response.data[0].userCriteria
          .split(';')
          .filter(Boolean)
          .map((id: string) => (isNaN(Number(id)) ? id : Number(id)));
      }
      return [];
    } catch (error) {
      console.error('Failed to fetch favorites from API', error);
      return [];
    }
  }

  /**
   * Saves favorite screen IDs for the current user to the backend.
   * @param ids - Array of screen IDs to save as favorites.
   */
  public async saveFavoriteScreens(ids: Array<string | number>): Promise<void> {
    const userId = localStorage.getItem('userId');
    const { plant } = useLocalizationStore();
    if (!userId || !plant) {
      return;
    }
    try {
      const preferences = [
        {
          plant: Number(plant),
          action: 'FAVORITE',
          appName: 'FAVORITES',
          userCriteria: ids.join(';'),
          user: { userId: Number(userId) },
        },
      ];
      await axios.post(`${this.umeBackend}/user-preference/save`, preferences, {
        headers: { authorization: `Bearer ${this.token}` },
      });
    } catch (error) {
      console.error('Failed to save favorites to API', error);
    }
  }

  async getMenuItems(): Promise<Array<MenuList>> {
    try {
      const response = await axios.get(`${this.umeBackend}/app-list`, {
        headers: {
          authorization: `Bearer ${this.token}`,
        },
      });
      return response.data as Array<MenuList>;
    } catch (error) {
      console.error('Error fetching menu items:', error);
      throw error;
    }
  }

  public async getPlantDetails(plant: number): Promise<any> {
    try {
      const baseUrl = this.umeBackend.replace(/\/ume-be$/, '');
      const response = await axios.get(
        `${baseUrl}/plt-hry-api/plant/getPlantById/${plant}`,
        {
          headers: {
            authorization: `Bearer ${this.token}`,
          },
        },
      );
      const plantDetails = response.data;
      return plantDetails;
    } catch {
      console.error('Error fetching plant details');
      return null;
    }
  }
}

export default ApiService;

import moment from 'moment-timezone';
import { defineStore } from 'pinia';
import storedAvailableLanguages from '../../localization/available-languages';
import en from '../../localization/locales/en.json';
import fr from '../../localization/locales/fr.json';
import ar from '../../localization/locales/ar.json';
import cz from '../../localization/locales/cz.json';
import es from '../../localization/locales/es-ES.json';
import mx from '../../localization/locales/es-MX.json';
import pl from '../../localization/locales/pl.json';
import br from '../../localization/locales/pt-BR.json';
import pt from '../../localization/locales/pt-PT.json';
import sk from '../../localization/locales/sk.json';
import cn from '../../localization/locales/zh-CN.json';
import hk from '../../localization/locales/zh-HK.json';





import apiService from '../service/api.ts';

export const useLocalizationStore = defineStore('localizationStore', {
  state: () => ({
    availableLanguages: storedAvailableLanguages,
    plant:
      JSON.parse(localStorage?.userAttributes ?? '{}')?.userAttributes?.plant ??
      (undefined as number | undefined),
    plantLocalization: undefined as string | undefined,

    plantSecondaryLocalizations: [] as Array<string>,

    plantTimezone:
      JSON.parse(localStorage?.userAttributes ?? '{}')?.userAttributes
        ?.timezone ?? '',
    userSelectedLocalization:
      sessionStorage.getItem('userSelectedLocalization') ?? undefined,
    userStoredLocalization: ((): string | undefined => {
      try {
        const locale =
          JSON.parse(localStorage?.userAttributes ?? '{}')?.userAttributes
            ?.locale ?? undefined;
        return locale ? locale.toLocaleUpperCase() : undefined;
      } catch {
        return undefined;
      }
    })(),
  }),

  getters: {
    localization(state): string {
      const supported = new Set(
        state.availableLanguages.map((lang) => lang.value),
      ); 
      if (
        state.userSelectedLocalization &&
        supported.has(state.userSelectedLocalization)
      ) {
        return state.userSelectedLocalization;
      }

      const pathSegments = globalThis.location.pathname
        .split('/')
        .filter(Boolean);
      const langFromUrl = pathSegments[1]?.toUpperCase();
      if (langFromUrl && supported.has(langFromUrl)) {
        return langFromUrl;
      }

      return state.userStoredLocalization ?? state.plantLocalization ?? 'EN';
    },
    validTimezone(state): string {
      const fallbackTz = Intl.DateTimeFormat().resolvedOptions().timeZone;
      const tz = state.plantTimezone;
      return tz && moment.tz.zone(tz) ? tz : fallbackTz;
    },

    orderedAvailableLanguages(state) {
    const supportedMap = new Map(
      state.availableLanguages.map(lang => [lang.value, lang])
    );
    const orderedList: typeof state.availableLanguages = [];
    const used = new Set<string>();

    const pushIfValid = (code?: string) => {
      if (!code) return;

      const upper = code.toUpperCase();
      if (used.has(upper)) return;

      const lang = supportedMap.get(upper);
      if (!lang) return;

      orderedList.push(lang);
      used.add(upper);
    };

    // 1. Locale language from custom attributes
      pushIfValid(state.userStoredLocalization);

    // 2. Main plant language (only if different)
    pushIfValid(state.plantLocalization);

      // 3. Secondary plant language(s)
      if (state.plantSecondaryLocalizations?.length > 0) {
        state.plantSecondaryLocalizations.forEach(pushIfValid);
      }
      // 4. Remaining supported languages
      else {
        state.availableLanguages.forEach((lang) => pushIfValid(lang.value));
      }
      return orderedList;
    },
  },

  actions: {
    async fetchPlantLocalizationIfNeeded(
      umeBackend: string,
      token: string,
    ): Promise<void> {
        try {
          const svc = new apiService(umeBackend, token);
        const plantDetails = await svc.getPlantDetails(this.plant);
          const newLocalizationUpper =
            plantDetails?.languageCode?.toLocaleUpperCase() ?? undefined;

            if (
        !this.userSelectedLocalization &&
        !this.userStoredLocalization &&
        !this.plantLocalization &&
        this.plant
      ) {
          if (newLocalizationUpper) {
            this.initializeUserSelection(newLocalizationUpper);
          }

        }
        this.plantLocalization = this.availableLanguages.some(
            (lang) => lang.value === newLocalizationUpper,
          )
            ? newLocalizationUpper
            : undefined;

          const raw = plantDetails?.secondaryLanguageCode;

          const secondaryCodes: string[] =
            typeof raw === 'string'
            ? raw
            .replace(/"/g, '')      // remove quotes
            .split(',')             // split by comma
            .map(code => code.trim().toUpperCase())
            .filter(Boolean)
          : [];
          this.plantSecondaryLocalizations =
             secondaryCodes;
        } catch (error) {
          console.error('Failed to fetch plant locale', error);
        }
    },
    initializeUserSelection(newLocalization: string): void {
      if (!this.userSelectedLocalization && newLocalization) {
        this.setUserSelectedLocalization(newLocalization);
      }
    },
    installCommonMessages(
      mergeLocaleMessage: (
        locale: string,
        messages: Record<string, string>,
      ) => void,
    ): void {
      mergeLocaleMessage('en', en);
      mergeLocaleMessage('fr', fr);
      mergeLocaleMessage('ar', ar);
      mergeLocaleMessage('cz', cz);
      mergeLocaleMessage('es-es', es);
      mergeLocaleMessage('es-mx', mx);
      mergeLocaleMessage('pl', pl);
      mergeLocaleMessage('pt-br', br);
      mergeLocaleMessage('pt-pt', pt);
      mergeLocaleMessage('sk', sk);
      mergeLocaleMessage('zh-cn', cn);
      mergeLocaleMessage('zh-hk', hk);

    },
    setPlant(newPlant: number | undefined): void {
      this.plant = newPlant;
    },
    setPlantTimezone(newTimezone: string | undefined): void {
      this.plantTimezone = newTimezone ?? '';
    },
    setUserSelectedLocalization(newLocalization: string): void {
      const newLocalizationUpper = newLocalization.toLocaleUpperCase();
      this.userSelectedLocalization = this.availableLanguages.some(
        (lang) => lang.value === newLocalizationUpper,
      )
        ? newLocalizationUpper
        : undefined;
      sessionStorage.setItem('userSelectedLocalization', newLocalizationUpper);
    },
    setUserStoredLocalization(newLocalization: string): void {
      const newLocalizationUpper = newLocalization.toLocaleUpperCase();
      this.userStoredLocalization = this.availableLanguages.some(
        (lang) => lang.value === newLocalizationUpper,
      )
        ? newLocalizationUpper
        : undefined;
      this.initializeUserSelection(newLocalizationUpper);
    },
  },
});

