  const supportUrl = ref<string | null>();

  const fetchMenuItems = async (
    umeBackend: string,
    token: string,
  ): Promise<Array<MenuList>> => {
    if (menuItems.value.length === 0) {
      try {
        const apiService = new ApiService(umeBackend, token);
        menuItems.value = await apiService.getMenuItems();
        return menuItems.value;
      } catch (error) {
        console.error(error);
        return [];
      }
    }
    return menuItems.value;
  };
  const fetchPlantLink = async (
    downtimeBackend: string,
    token: string,
    plant: number,
  ): Promise<string | undefined> => {
    if (plantItems.value.length === 0) {
      try {
        const apiService = new ApiService(downtimeBackend, token);
        const result = await apiService.getPlantLink(plant);
        plantItems.value = result === undefined ? [] : [result];
        return plantItems.value[0];
      } catch (error) {
        console.error(error);
        return '';
      }
    }

    return plantItems.value[0];
  };

  const fetchSupportUrl = async (
    path: string,
    umeBackend: string,
    token: string,
  ): Promise<string | null> => {
    const apiService = new ApiService(umeBackend, token);
    supportUrl.value = await apiService.fetchSupportUrlFromBackend(path);
    return supportUrl.value;
  };

  return {
    fetchMenuItems,
    fetchPlantLink,
    menuItems,
    supportUrl,
    fetchSupportUrl,
  };
});

