}

import type { AppPageList, MenuList } from '../types/menu-list';
import type { ValidationMatchResult } from '../types/validation';

export type { ValidationMatchResult } from '../types/validation';

const collectAllMenuItems = (items: Array<MenuList>): Array<MenuList> => {
  const result: Array<MenuList> = [];
  const stack: Array<MenuList> = [...items];

  while (stack.length > 0) {
    const item = stack.pop();
    if (!item) continue;
    result.push(item);
    if (item.children) for (const child of item.children) stack.push(child);
  }

  return result;
};

/**
 * Builds a map of parent relationships for menu items.
 * @param items
 */
const buildParentMap = (
  items: Array<MenuList>,
): Map<MenuList, MenuList | null> => {
  const parentMap = new Map<MenuList, MenuList | null>();
  const stack = items.map((item) => ({
    item,
    parent: null as MenuList | null,
  }));

  while (stack.length > 0) {
    const { item, parent } = stack.pop()!;
    parentMap.set(item, parent);
    if (item.children)
      for (const child of item.children)
        stack.push({ item: child, parent: item });
  }

  return parentMap;
};

/**
 * Checks if any ancestor of the item is not validated.
 * @param item
 * @param parentMap
 * @param menuWithPagesMap
 */
const hasInvalidAncestor = (
  item: MenuList | AppPageList,
  parentMap: Map<MenuList, MenuList | null>,
  menuWithPagesMap: Map<AppPageList, MenuList>,
): boolean => {
  let current = ('pageId' in item ? menuWithPagesMap.get(item) : item) as
    | MenuList
    | null
    | undefined;

  while (current) {
    if (current.isValidated === false) return true;
    current = parentMap.get(current) ?? null;
  }

  return false;
};

// Helper to check ancestors
const getValidationResult = (
  item: MenuList | AppPageList,
  kind: 'menu' | 'page',
  link: string,
  parentMap: Map<MenuList, MenuList | null>,
  menuWithPagesMap: Map<AppPageList, MenuList>,
) => {
  let isValidated: boolean;
  isValidated =
    kind === 'menu'
      ? (item as MenuList).isValidated !== false &&
        !hasInvalidAncestor(item, parentMap, menuWithPagesMap)
      : (item as AppPageList).isValidated &&
        !hasInvalidAncestor(item, parentMap, menuWithPagesMap);
  return {
    isValidated,
    matchedKind: kind,
    matchedLink: link,
  };
};

/**
 * Checks if a routePath matches a static link, allowing for dynamic segments.
 * Matches if routePath ends with link, or is exactly equal.
 * @param routePath
 * @param link
 */
function pathMatches(routePath: string, link: string): boolean {
  if (!routePath || !link) return false;
  // Remove query/hash from routePath
  const cleanRoute = routePath.split(/[#?]/)[0];
  // Match if link is contained anywhere in the routePath (as a path segment)
  // E.g. /downtime-ui/ELAA1/split_screen/166500001479 contains /split_screen
  return cleanRoute === link || cleanRoute.includes(link);
}

/**
 * Finds the best (deepest/longest) match for routePath among pages and menus.
 * @param routePath
 * @param menuWithPagesMap
 * @param allMenus
 */
function findBestValidationMatch(
  routePath: string,
  menuWithPagesMap: Map<AppPageList, MenuList>,
  allMenus: Array<MenuList>,
): {
  item: MenuList | AppPageList;
  kind: 'menu' | 'page';
  link: string;
  length: number;
} | null {
  let bestMatch: {
    item: MenuList | AppPageList;
    kind: 'menu' | 'page';
    link: string;
    length: number;
  } | null = null;
  // Check all pages (children)
  for (const [page] of menuWithPagesMap.entries()) {
    if (pathMatches(routePath, page.link)) {
      const length_ = page.link.length;
      if (!bestMatch || length_ > bestMatch.length) {
        bestMatch = {
          item: page,
          kind: 'page',
          link: page.link,
          length: length_,
        };
      }
    }
  }
  // Check all menus (parents)
  for (const menu of allMenus) {
    if (pathMatches(routePath, menu.link)) {
      const length_ = menu.link.length;
      if (!bestMatch || length_ > bestMatch.length) {
        bestMatch = {
          item: menu,
          kind: 'menu',
          link: menu.link,
          length: length_,
        };
      }
    }
  }
  return bestMatch;
}

export const findValidationStatus = (
  menuItems: Array<MenuList>,
  appName?: string,
  routePath?: string,
  availableLanguages?: Array<string>,
): ValidationMatchResult => {
  // --- Optimization: Remove debug log ---
  if (!Array.isArray(menuItems) || menuItems.length === 0)
    return { isValidated: true };
  const allMenus = collectAllMenuItems(menuItems);
  const parentMap = buildParentMap(menuItems);
  const menuWithPagesMap = new Map<AppPageList, MenuList>();
  for (const menu of allMenus)
    if (menu.pages)
      for (const page of menu.pages) menuWithPagesMap.set(page, menu);

  // --- Optimization: Path matching for dynamic segments ---
  /**
   * Normalizes a string for comparison (lowercase, trimmed, single spaces).
   * @param s
   */
  const normalize = (s?: string) =>
    (s || '').toLowerCase().replace(/\s+/g, ' ').trim();

  if (
    routePath &&
    Array.isArray(availableLanguages) &&
    availableLanguages.length > 0
  ) {
    const hasLang = availableLanguages.some((lang) =>
      routePath.includes(`/${lang}/`),
    );
    if (!hasLang) {
      const bestMatch = findBestValidationMatch(
        routePath,
        menuWithPagesMap,
        allMenus,
      );
      if (bestMatch) {
        return getValidationResult(
          bestMatch.item,
          bestMatch.kind,
          bestMatch.link,
          parentMap,
          menuWithPagesMap,
        );
      }
      // If not found, consider validated
      return { isValidated: true };
    }
  }

  // Fallback to old logic (by appName)
  if (!appName) {
    return { isValidated: true };
  }
  const target = normalize(appName);
  const allPages = [...menuWithPagesMap.keys()];
  for (const page of allPages) {
    const pageNorm = normalize(page?.pageName);
    if (pageNorm && (pageNorm.includes(target) || target.includes(pageNorm))) {
      return {
        isValidated:
          page.isValidated &&
          !hasInvalidAncestor(page, parentMap, menuWithPagesMap),
        matchedKind: 'page',
        matchedLink: page.link,
      };
    }
  }
  for (const menu of allMenus) {
    const menuNorm = normalize(menu?.appName);
    if (menuNorm && (menuNorm.includes(target) || target.includes(menuNorm))) {
      return {
        isValidated:
          menu.isValidated !== false &&
          !hasInvalidAncestor(menu, parentMap, menuWithPagesMap),
        matchedKind: 'menu',
        matchedLink: menu.link,
      };
    }
  }
  return { isValidated: true };
};

/**
 * Removes leading zeros from a string or number.
 * @param material - The string or number to process.
 * @returns The processed string without leading zeros.
 */
export function removeLeadingZeros(
  material: string | number | null | undefined,
): string {
  if (!material) return '';
  return String(material).replace(/^0+/, '');
}

class AppLogger {
  log(message: unknown): void {
    /* eslint class-methods-use-this: "off" */
    /* eslint no-console: "off" */
    console.log(`${new Date().toISOString()} -- ${message}`);
  }

  error(message: unknown, stack?: string): void {
    /* eslint class-methods-use-this: "off" */
    /* eslint no-console: "off" */
    console.error(`${new Date().toISOString()} -- ${message}`, stack);
  }

  warn(message: unknown): void {
    /* eslint class-methods-use-this: "off" */
    /* eslint no-console: "off" */
    console.warn(`${new Date().toISOString()} -- ${message}`);
  }

  debug(message: unknown): void {
    /* eslint class-methods-use-this: "off" */
    /* eslint no-console: "off" */
    console.debug(`${new Date().toISOString()} -- ${message}`);
  }

  verbose(message: unknown): void {
    /* eslint class-methods-use-this: "off" */
    /* eslint no-console: "off" */
    console.info(`${new Date().toISOString()} -- ${message}`);
  }
}
const appLogger = new AppLogger();

export { appLogger };

